class TestFilterIntegers(unittest.TestCase):
    def test_filter_integers_normal_mixed_types(self):
        self.assertEqual(filter_integers(['a', 3.14, 5]), [5])

    def test_filter_integers_empty_input(self):
        self.assertEqual(filter_integers([]), [])

    def test_filter_integers_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            filter_integers(None)

    def test_filter_integers_single_integer(self):
        self.assertEqual(filter_integers([42]), [42])

    def test_filter_integers_single_non_integer(self):
        self.assertEqual(filter_integers(['hello']), [])

    def test_filter_integers_booleans_included_as_integers(self):
        self.assertEqual(filter_integers([True, False, 1, 0]), [True, False, 1, 0])

    def test_filter_integers_floats_excluded(self):
        self.assertEqual(filter_integers([1.5, 2.7, 3]), [3])

    def test_filter_integers_strings_excluded(self):
        self.assertEqual(filter_integers(['abc', '123', '']), [])

    def test_filter_integers_nested_structures_excluded(self):
        self.assertEqual(filter_integers([{'a': 1}, [1, 2], {'b': 3}]), [])

    def test_filter_integers_preserves_positive_integers(self):
        self.assertEqual(filter_integers([1, 2, 3, 'abc', {}, []]), [1, 2, 3])

